import React, { useState, useEffect } from "react";
import api from "../../api";
import { FaPlus } from "react-icons/fa";

const Corousel = () => {
  const [data, setData] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    gambar: null
  });
  const [loading, setLoading] = useState(false); // Tambahkan state loading

  useEffect(() => {
    api.get('/corousel')
      .then(response => {
        setData(response.data.carousel);
      })
      .catch(error => {
        console.error("Error fetching data:", error);
      });
  }, []);

  const handleOpenModal = () => {
    setShowModal(true);
    setFormData({
      name: "",
      gambar: null
    });
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    setFormData(prev => ({ ...prev, gambar: file }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true); // Set loading to true when form is being submitted

    const formDataToSend = new FormData();
    formDataToSend.append('name', formData.name);
    if (formData.gambar) formDataToSend.append('gambar', formData.gambar);

    api.post('/corousel/create', formDataToSend)
      .then(response => {
        setData([...data, response.data]);
        handleCloseModal();
        setLoading(false);
      })
      .catch(error => {
        console.error("Error submitting form:", error);
        setLoading(false); // Set loading to false in case of error
      });
  };

  return (
    <div>
      {/* Button Create Corousel */}
      <button
        onClick={handleOpenModal}
        className="bg-teal-500 text-white py-2 px-4 rounded-lg mb-4 flex items-center"
      >
        <FaPlus className="inline-block mr-2 mb-1" /> Create Corousel
      </button>

      {/* Tampilkan tabel carousel */}
      <div className="grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Name</th>
              <th className="px-6 py-3 text-left font-medium">Gambar</th>
              <th className="px-6 py-3 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody>
            {data && data.length > 0 ? (
              data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.name}</td>
                  <td className="px-6 py-4">
                    <img src={row.gambar} alt={row.name} className="w-16 h-16 object-cover" />
                  </td>
                  <td className="px-6 py-4">
                    <button
                      onClick={handleOpenModal}
                      className="bg-teal-500 text-white py-1 px-3 rounded-lg"
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="4" className="text-center px-6 py-4 text-gray-500">
                  Tidak ada data carousel tersedia.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Modal Form */}
      {showModal && (
        <div className="fixed inset-0 modal-overlay flex justify-center items-center z-50">
          <div className="modal-content animate__animated animate__zoomIn animate__faster">
            <h2 className="text-2xl font-semibold text-teal-700 mb-6 text-center">Tambah Corousel</h2>
            <form onSubmit={handleSubmit}>
              <div className="mb-6">
                <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-2">
                  Name
                </label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                  placeholder="Masukkan nama Corousel"
                />
              </div>
      
              <div className="mb-6">
                <label htmlFor="gambar" className="block text-sm font-medium text-gray-700 mb-2">
                  Gambar
                </label>
                <input
                  type="file"
                  id="gambar"
                  name="gambar"
                  onChange={handleFileChange}
                  className="w-full p-3 border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                />
              </div>
      
              <div className="flex justify-end gap-4">
                <button
                  type="button"
                  onClick={handleCloseModal}
                  className="bg-gray-300 text-gray-800 py-2 px-6 rounded-lg font-semibold hover:bg-gray-400 transition duration-200"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="bg-teal-600 text-white py-2 px-6 rounded-lg font-semibold hover:bg-teal-700 transition duration-200"
                >
                  Submit
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Loading Spinner */}
      {loading && (
        <div className="fixed inset-0 bg-gray-800 bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg">
            <div className="flex justify-center">
              <div className="animate-spin rounded-full border-t-4 border-teal-500 h-16 w-16"></div>
            </div>
            <p className="text-center mt-4 text-teal-700">Sedang memproses...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Corousel;
